{"Table":"es_tb_posts","Create Table":"CREATE TABLE `es_tb_posts` (\n  `id` varchar(36) NOT NULL,\n  `title` varchar(255) NOT NULL,\n  `text` text NOT NULL,\n  `owner` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `FK_POST_OWNER` (`owner`),\n  CONSTRAINT `FK_POST_OWNER` FOREIGN KEY (`owner`) REFERENCES `es_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"es_tb_posts.sql","path":"files/sql/rod/es_tb_posts.sql","sha":"1d25d1ba5f7dd7b3a7b86820aae3a65dd9c5ccb1","size":1071532,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/es_tb_posts.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/es_tb_posts.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/1d25d1ba5f7dd7b3a7b86820aae3a65dd9c5ccb1","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/es_tb_posts.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/es_tb_posts.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/1d25d1ba5f7dd7b3a7b86820aae3a65dd9c5ccb1","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/es_tb_posts.sql"}},"pairedItem":{"item":22},"index":22}